// n8n Code node — Mode: "Run Once for All Items", Language: JavaScript
// Cleans student records produced by an AI node (OpenAI, AI Agent, etc.).
// Works whether the 50 records arrive as:
//   - 50 separate items, each with one record in a "text" / "output" field
//   - 1 item holding all records (a JSON array, or several objects in one string)
//   - JSON wrapped in ```json fences or surrounded by extra AI text
//   - double-encoded JSON (a JSON string inside a JSON string)
// Output: one cleaned item per student, with _issues and _valid flags.

const MONTHS = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, oct:10, nov:11, dec:12 };

// ---------- Parsing the AI output ----------

// Pick the field that holds the AI text
function getSourceText(json) {
  if (json.Student_ID !== undefined) return json;           // already parsed record
  const candidates = [json.text, json.output, json.response, json.content,
                      json.message?.content, json.choices?.[0]?.message?.content];
  for (const c of candidates) if (c !== undefined && c !== null) return c;
  return json;
}

// Try JSON.parse, unwrapping strings that are JSON-encoded twice
function tryParse(str) {
  let value = JSON.parse(str);
  let guard = 0;
  while (typeof value === 'string' && guard++ < 3) value = JSON.parse(value);
  return value;
}

// Turn whatever the AI returned into an array of record objects
function extractRecords(source) {
  if (Array.isArray(source)) return source.flatMap(extractRecords);
  if (source && typeof source === 'object') {
    if (source.Student_ID !== undefined) return [source];
    // e.g. { "students": [...] } or { "records": [...] }
    for (const v of Object.values(source)) if (Array.isArray(v)) return v.flatMap(extractRecords);
    return [source];
  }

  let str = String(source).trim();
  // Remove markdown code fences the AI may add
  str = str.replace(/```(?:json)?/gi, '').trim();

  // 1. Whole string is valid JSON
  try { return extractRecords(tryParse(str)); } catch (e) {}

  // 2. Escaped quotes left in (\"Name\":\"X\")
  try { return extractRecords(tryParse(str.replace(/\\"/g, '"'))); } catch (e) {}

  // 3. Several objects in one string, or JSON mixed with prose: pull out each {...}
  const unescaped = str.replace(/\\"/g, '"');
  const matches = unescaped.match(/\{[^{}]*\}/g) || [];
  const found = [];
  for (const m of matches) {
    try { found.push(JSON.parse(m)); } catch (e) {}
  }
  if (found.length) return found;

  throw new Error('No JSON records found');
}

// ---------- Cleaning helpers ----------

function cleanText(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().replace(/\s+/g, ' ');
  return s || null;
}

function toTitleCase(v) {
  const s = cleanText(v);
  if (!s) return null;
  return s.toLowerCase().replace(/\b([a-z])/g, c => c.toUpperCase());
}

function cleanEmail(v) {
  const s = cleanText(v);
  if (!s) return null;
  const e = s.toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e) ? e : null;
}

function cleanPhone(v) {
  if (v === null || v === undefined) return null;
  let d = String(v).replace(/\D/g, '');
  if (d.length === 12 && d.startsWith('91')) d = d.slice(2);   // +91XXXXXXXXXX
  if (d.length === 11 && d.startsWith('0')) d = d.slice(1);    // 0XXXXXXXXXX
  return /^[6-9]\d{9}$/.test(d) ? d : null;                    // Indian mobile
}

function cleanBool(v) {
  if (typeof v === 'boolean') return v;
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toLowerCase();
  if (['true', 'yes', 'y', '1', 'paid'].includes(s)) return true;
  if (['false', 'no', 'n', '0', 'unpaid', 'not paid'].includes(s)) return false;
  return null;
}

function buildDate(y, m, d) {
  y = Number(y); m = Number(m); d = Number(d);
  if (!y || !m || !d) return null;
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

const monthNum = name => MONTHS[String(name).slice(0, 3).toLowerCase()];

// Accepts: 2025-05-23, 2025/05/23, 2025-May-23, 23-May-2025, 23 May 2025,
//          23rd May 2025, May 23, 2025, 23/05/2025 (read as DD/MM/YYYY)
function cleanDate(v) {
  let s = cleanText(v);
  if (!s) return null;
  s = s.replace(/(\d)(st|nd|rd|th)\b/gi, '$1');
  let m;
  if ((m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/))) return buildDate(m[1], m[2], m[3]);
  if ((m = s.match(/^(\d{4})[-\/ ]([A-Za-z]{3,})[-\/ ](\d{1,2})$/))) return buildDate(m[1], monthNum(m[2]), m[3]);
  if ((m = s.match(/^(\d{1,2})[-\/ ]([A-Za-z]{3,})[-\/ ,]+(\d{4})$/))) return buildDate(m[3], monthNum(m[2]), m[1]);
  if ((m = s.match(/^([A-Za-z]{3,})[ -](\d{1,2}),?[ -](\d{4})$/))) return buildDate(m[3], monthNum(m[1]), m[2]);
  if ((m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/))) return buildDate(m[3], m[2], m[1]);
  return null;
}

// ---------- Main ----------

const output = [];
const seenIds = new Set();

for (const item of $input.all()) {
  let records;
  try {
    records = extractRecords(getSourceText(item.json));
  } catch (err) {
    output.push({ json: { _raw: JSON.stringify(item.json).slice(0, 500), _issues: ['Could not parse AI output'], _valid: false } });
    continue;
  }

  for (const raw of records) {
    const issues = [];
    const cleaned = {
      Student_ID: cleanText(raw.Student_ID)?.toUpperCase() ?? null,
      Name: cleanText(raw.Name),          // keeps original case; only trims extra spaces
      Email: cleanEmail(raw.Email),
      Phone: cleanPhone(raw.Phone),
      Course: cleanText(raw.Course),
      Fee_Paid: cleanBool(raw.Fee_Paid),
      City: toTitleCase(raw.City),
      Enrolled_Date: cleanDate(raw.Enrolled_Date),
    };

    if (!cleaned.Student_ID) issues.push('Missing Student_ID');
    else if (seenIds.has(cleaned.Student_ID)) issues.push('Duplicate Student_ID');
    else seenIds.add(cleaned.Student_ID);

    if (!cleaned.Name) issues.push('Missing Name');
    if (!cleaned.Email) issues.push(`Invalid email: ${raw.Email ?? 'blank'}`);
    if (!cleaned.Phone) issues.push(`Invalid phone: ${raw.Phone ?? 'blank'}`);
    if (!cleaned.Course) issues.push('Missing Course');
    if (cleaned.Fee_Paid === null) issues.push(`Unclear Fee_Paid: ${raw.Fee_Paid ?? 'blank'}`);
    if (!cleaned.Enrolled_Date) issues.push(`Invalid date: ${raw.Enrolled_Date ?? 'blank'}`);

    cleaned._issues = issues;
    cleaned._valid = issues.length === 0;
    output.push({ json: cleaned });
  }
}

return output;
